	public static function supports( string $route, string $action ): bool {
		$route = '/' . trim( $route, '/' );
		$action = sanitize_key( $action );
		return isset( self::ROUTE_ACTIONS[ $route ] ) && in_array( $action, self::ROUTE_ACTIONS[ $route ], true );
	}

	public static function action_map(): array { return self::ROUTE_ACTIONS; }

	public static function boot(): void {
		add_action( 'init', array( __CLASS__, 'register_runtime_definitions' ), 4 );
		add_action( 'template_redirect', array( __CLASS__, 'apply_managed_redirects' ), 0 );
		add_action( 'wp_head', array( __CLASS__, 'render_managed_seo_head' ), 2 );
		add_action( 'wp_footer', array( __CLASS__, 'render_managed_frontend_scripts' ), 99 );
		add_filter( 'pre_get_document_title', array( __CLASS__, 'filter_document_title' ), 99, 1 );
		add_filter( 'robots_txt', array( __CLASS__, 'filter_robots_txt' ), 99, 2 );
		add_filter( 'script_loader_tag', array( __CLASS__, 'apply_script_sri' ), 99, 3 );
		add_filter( 'style_loader_tag', array( __CLASS__, 'apply_style_sri' ), 99, 4 );
		add_filter( 'rank_math/json_ld', array( __CLASS__, 'rank_math_json_ld' ), 99, 2 );
		add_filter( 'wpseo_schema_graph', array( __CLASS__, 'yoast_schema_graph' ), 99, 2 );
		add_action( 'send_headers', array( __CLASS__, 'send_managed_security_headers' ), 20 );
		add_action( 'init', array( __CLASS__, 'enforce_blocked_ips' ), 0 );
		add_action( 'prstudio_uc_expire_post', array( __CLASS__, 'expire_post' ), 10, 1 );
	}

	public static function execute( string $route, string $action, array $args, array $meta = array() ) {
		$route = '/' . trim( $route, '/' );
		$action = sanitize_key( $action );
		if ( ! self::supports( $route, $action ) ) { return new WP_Error( 'prstudio_complete_executor_action_unknown', 'Azione non registrata nel complete executor.', array( 'status' => 404, 'route' => $route, 'action' => $action ) ); }
		$handler = 'route_' . str_replace( '-', '_', trim( $route, '/' ) );
		if ( ! is_callable( array( __CLASS__, $handler ) ) ) { return new WP_Error( 'prstudio_complete_executor_route_missing', 'Executor di route non disponibile.', array( 'status' => 500, 'route' => $route, 'action' => $action ) ); }
		try {
			$result = self::{$handler}( $action, $args, $meta );
		} catch ( Throwable $error ) {
			return new WP_Error( 'prstudio_complete_executor_exception', $error->getMessage(), array( 'status' => 500, 'route' => $route, 'action' => $action, 'exception' => get_class( $error ) ) );
		}
		if ( null === $result ) { return new WP_Error( 'prstudio_complete_executor_null', 'L’executor ha restituito null: contratto operativo violato.', array( 'status' => 500, 'route' => $route, 'action' => $action ) ); }
		return $result;
	}

	private static function v( array $args, string $key, $default = null ) {
		if ( array_key_exists( $key, $args ) ) { return $args[ $key ]; }
		foreach ( array( 'params', 'body', 'query' ) as $container ) {
			if ( isset( $args[ $container ] ) && is_array( $args[ $container ] ) && array_key_exists( $key, $args[ $container ] ) ) { return $args[ $container ][ $key ]; }
		}
		return $default;
	}

	private static function limit( array $args, int $default = 50, int $max = self::MAX_BATCH ): int {
		return max( 1, min( $max, (int) self::v( $args, 'limit', self::v( $args, 'per_page', $default ) ) ) );
	}

	private static function ids( array $args, string $single_key = 'id', string $many_key = 'ids', int $max = self::MAX_BATCH ): array {
		$ids = array_filter( array_map( 'absint', (array) self::v( $args, $many_key, array() ) ) );
		$single = absint( self::v( $args, $single_key, 0 ) );
		if ( $single ) { $ids[] = $single; }
		return array_slice( array_values( array_unique( $ids ) ), 0, $max );
	}

	private static function mutation( array $data, bool $verified = true, string $reason = '' ): array {
		$data['degraded'] = ! $verified;
		$data['blocking'] = false;
		$data['_control_outcome'] = array(
			'status' => $verified ? 'completed' : 'degraded',
			'executed' => true,
			'mutated' => true,
			'verified' => $verified,
			'degraded' => ! $verified,
			'blocking' => false,
			'reason' => $reason,
		);
		return $data;
	}

	private static function verified_no_change( array $data, string $reason = 'verified_no_change' ): array {
		$data['_control_outcome'] = array( 'status' => 'verified', 'executed' => true, 'mutated' => false, 'verified' => true, 'reason' => $reason );
		return $data;
	}

	private static function admin_user_id(): int {
		$users = get_users( array( 'role__in' => array( 'administrator' ), 'number' => 1, 'fields' => 'ID', 'orderby' => 'ID', 'order' => 'ASC' ) );
		return $users ? (int) $users[0] : 0;
	}

	private static function rest( string $method, string $route, array $query = array(), array $body = array() ) {
		$method = strtoupper( sanitize_text_field( $method ) );
		$route = '/' . ltrim( $route, '/' );
		if ( ! in_array( $method, array( 'GET', 'POST', 'PUT', 'PATCH', 'DELETE' ), true ) ) { return new WP_Error( 'prstudio_rest_method_invalid', 'Metodo REST interno non valido.', array( 'status' => 400 ) ); }
		if ( ! preg_match( '#^/(?:wp/v2|wc/v3|wc-analytics|wp-site-health/v1)/#', $route ) ) { return new WP_Error( 'prstudio_rest_route_forbidden', 'Route REST interna fuori allowlist.', array( 'status' => 403, 'route' => $route ) ); }
		$before = get_current_user_id(); $admin = self::admin_user_id(); if ( $admin ) { wp_set_current_user( $admin ); }
		try {
			$request = new WP_REST_Request( $method, $route );
			if ( $query ) { $request->set_query_params( $query ); }
			if ( $body ) { $request->set_body_params( $body ); $request->set_header( 'content-type', 'application/json' ); }
			$response = rest_do_request( $request );
		} finally { wp_set_current_user( $before ); }
		if ( is_wp_error( $response ) ) { return $response; }
		$status = method_exists( $response, 'get_status' ) ? (int) $response->get_status() : 200;
		$data = method_exists( $response, 'get_data' ) ? $response->get_data() : null;
		if ( $status >= 400 ) { return new WP_Error( 'prstudio_internal_rest_failed', 'REST interna ha restituito errore.', array( 'status' => $status, 'route' => $route, 'response' => $data ) ); }
		return array( 'status' => $status, 'route' => $route, 'data' => $data );
	}

	private static function rel_path( string $path ): string {
		$path = wp_normalize_path( trim( $path ) );
		$base = wp_normalize_path( ABSPATH );
		if ( 0 === strpos( $path, $base ) ) { $path = substr( $path, strlen( $base ) ); }
		$path = ltrim( $path, '/' );
		if ( '' === $path || preg_match( '#(^|/)\.\.(/|$)#', $path ) || str_contains( $path, "\0" ) ) { throw new InvalidArgumentException( 'Percorso non valido o traversal rilevato.' ); }
		return $path;
	}

	private static function abs_path( string $path, bool $must_exist = false ): string {
		$rel = self::rel_path( $path );
		$abs = wp_normalize_path( trailingslashit( ABSPATH ) . $rel );
		$allowed = array( wp_normalize_path( ABSPATH ), wp_normalize_path( WP_CONTENT_DIR ) );
		$ok = false; foreach ( $allowed as $root ) { if ( 0 === strpos( $abs, trailingslashit( $root ) ) || $abs === untrailingslashit( $root ) ) { $ok = true; break; } }
		if ( ! $ok ) { throw new InvalidArgumentException( 'Percorso fuori sandbox WordPress.' ); }
		if ( $must_exist && ! file_exists( $abs ) ) { throw new RuntimeException( 'Percorso non esistente: ' . $rel ); }
		return $abs;
	}

	private static function write_text( string $path, string $content, ?string $expected = null ) {
		$rel = self::rel_path( $path );
		$abs = self::abs_path( $rel, false );
		if ( file_exists( $abs ) && null === $expected ) { $expected = hash_file( 'sha256', $abs ); }
		return WPAIB_Files::write_raw( $rel, $content, $expected );
	}

	private static function delete_path( string $path ) {
		$rel = self::rel_path( $path ); $abs = self::abs_path( $rel, true );
		if ( is_dir( $abs ) ) {
			$files = new RecursiveIteratorIterator( new RecursiveDirectoryIterator( $abs, FilesystemIterator::SKIP_DOTS ), RecursiveIteratorIterator::CHILD_FIRST );
			$count = 0; foreach ( $files as $file ) { if ( ++$count > self::MAX_SCAN_FILES ) { return new WP_Error( 'prstudio_delete_limit', 'Directory troppo grande per eliminazione bounded.', array( 'status' => 413 ) ); } $file->isDir() ? @rmdir( $file->getPathname() ) : @unlink( $file->getPathname() ); }
			return self::mutation( array( 'path' => $rel, 'deleted' => @rmdir( $abs ) ) );
		}
		return WPAIB_Files::delete_file( $rel, hash_file( 'sha256', $abs ) );
	}

	private static function list_files( string $path, int $max = self::MAX_SCAN_FILES, array $extensions = array() ): array {
		$abs = self::abs_path( $path, true ); $out = array();
		$extensions = array_map( static fn( $v ) => strtolower( ltrim( (string) $v, '.' ) ), $extensions );
		if ( is_file( $abs ) ) { return array( self::rel_path( $abs ) ); }
		$it = new RecursiveIteratorIterator( new RecursiveDirectoryIterator( $abs, FilesystemIterator::SKIP_DOTS ) );
		foreach ( $it as $file ) {
			if ( ! $file->isFile() ) { continue; }
			if ( $extensions && ! in_array( strtolower( $file->getExtension() ), $extensions, true ) ) { continue; }
			$out[] = self::rel_path( $file->getPathname() ); if ( count( $out ) >= $max ) { break; }
		}
		return $out;
	}

	private static function runtime_config(): array { $cfg = get_option( 'prstudio_uc_complete_runtime', array() ); return is_array( $cfg ) ? $cfg : array(); }
	private static function save_runtime_config( array $cfg ): bool { return update_option( 'prstudio_uc_complete_runtime', $cfg, false ) || get_option( 'prstudio_uc_complete_runtime', array() ) === $cfg; }

	private static function set_runtime_section( string $section, $value ): array {
		$cfg = self::runtime_config(); $before = $cfg[ $section ] ?? null; $cfg[ $section ] = $value; $ok = self::save_runtime_config( $cfg );
		$after = self::runtime_config()[ $section ] ?? null;
		if ( ! $ok || $after !== $value ) { return array( 'ok' => false, 'before' => $before, 'after' => $after ); }
		return array( 'ok' => true, 'before' => $before, 'after' => $after );
	}

	private static function update_runtime_map( string $section, string $key, $value, bool $delete = false ): array {
		$cfg = self::runtime_config(); $map = is_array( $cfg[ $section ] ?? null ) ? $cfg[ $section ] : array(); $before = $map;
		if ( $delete ) { unset( $map[ $key ] ); } else { $map[ $key ] = $value; }
		$cfg[ $section ] = $map; self::save_runtime_config( $cfg );
		$after = is_array( self::runtime_config()[ $section ] ?? null ) ? self::runtime_config()[ $section ] : array();
		return array( 'before' => $before, 'after' => $after, 'verified' => $after === $map );
	}

	private static function ensure_admin_include( string $file ): void { $path = ABSPATH . 'wp-admin/includes/' . $file; if ( is_file( $path ) ) { require_once $path; } }

	private static function application_passwords_available(): bool { return class_exists( 'WP_Application_Passwords' ) && method_exists( 'WP_Application_Passwords', 'create_new_application_password' ); }

	private static function normalize_html_text( string $text, int $max = 300 ): string { return mb_substr( trim( preg_replace( '/\s+/u', ' ', wp_strip_all_tags( $text ) ) ), 0, $max ); }

	private static function post_ids_from_args( array $args ): array {
		$ids = self::ids( $args ); if ( $ids ) { return $ids; }
		$post_type = sanitize_key( (string) self::v( $args, 'post_type', 'post' ) );
		return get_posts( array( 'post_type' => $post_type ?: 'post', 'post_status' => 'any', 'fields' => 'ids', 'posts_per_page' => self::limit( $args, 50, self::MAX_BATCH ), 's' => (string) self::v( $args, 'search', '' ) ) );
	}
	public static function register_runtime_definitions(): void {
		$cfg = self::runtime_config();
		foreach ( (array) ( $cfg['post_types'] ?? array() ) as $key => $definition ) {
			if ( post_type_exists( $key ) || ! is_array( $definition ) ) { continue; }
			register_post_type( sanitize_key( $key ), $definition );
		}
		foreach ( (array) ( $cfg['post_statuses'] ?? array() ) as $key => $definition ) {
			if ( get_post_status_object( $key ) || ! is_array( $definition ) ) { continue; }
			register_post_status( sanitize_key( $key ), $definition );
		}
		foreach ( (array) ( $cfg['taxonomies'] ?? array() ) as $key => $definition ) {
			if ( taxonomy_exists( $key ) || ! is_array( $definition ) ) { continue; }
			$objects = array_values( array_filter( array_map( 'sanitize_key', (array) ( $definition['object_type'] ?? array( 'post' ) ) ) ) );
			$args = is_array( $definition['args'] ?? null ) ? $definition['args'] : array();
			register_taxonomy( sanitize_key( $key ), $objects ?: array( 'post' ), $args );
		}
	}

	public static function apply_managed_redirects(): void {
		if ( is_admin() || wp_doing_ajax() || wp_doing_cron() ) { return; }
		$cfg = self::runtime_config(); $uri = sanitize_text_field( wp_unslash( (string) ( $_SERVER['REQUEST_URI'] ?? '/' ) ) ); $path = (string) wp_parse_url( $uri, PHP_URL_PATH );
		foreach ( (array) ( $cfg['redirects'] ?? array() ) as $source => $entry ) {
			if ( ! is_array( $entry ) ) { continue; }
			$source_path = (string) wp_parse_url( $source, PHP_URL_PATH ); if ( '' === $source_path ) { $source_path = $source; }
			if ( untrailingslashit( $source_path ) !== untrailingslashit( $path ) ) { continue; }
			$status = max( 300, min( 399, (int) ( $entry['status'] ?? 301 ) ) );
			$target = esc_url_raw( (string) ( $entry['target'] ?? '' ) );
			if ( $target ) { wp_safe_redirect( $target, $status, 'PR STUDIO' ); exit; }
		}
		foreach ( (array) ( $cfg['gone_410'] ?? array() ) as $gone ) {
			$gone_path = (string) wp_parse_url( (string) $gone, PHP_URL_PATH );
			if ( untrailingslashit( $gone_path ?: (string) $gone ) === untrailingslashit( $path ) ) { status_header( 410 ); nocache_headers(); exit; }
		}
	}

	private static function current_seo_record(): array {
		$cfg = self::runtime_config(); $seo = is_array( $cfg['seo'] ?? null ) ? $cfg['seo'] : array();
		$id = is_singular() ? get_queried_object_id() : 0;
		if ( $id && is_array( $seo['post'][ (string) $id ] ?? null ) ) { return $seo['post'][ (string) $id ]; }
		if ( is_category() || is_tag() || is_tax() ) {
			$obj = get_queried_object(); if ( $obj && isset( $obj->term_id ) && is_array( $seo['term'][ (string) $obj->term_id ] ?? null ) ) { return $seo['term'][ (string) $obj->term_id ]; }
		}
		if ( is_author() ) { $obj = get_queried_object(); if ( $obj && isset( $obj->ID ) && is_array( $seo['user'][ (string) $obj->ID ] ?? null ) ) { return $seo['user'][ (string) $obj->ID ]; } }
		return is_array( $seo['global'] ?? null ) ? $seo['global'] : array();
	}

	private static function normalized_record_schemas( array $record ): array {
		$schemas = $record['schema'] ?? array();
		if ( is_string( $schemas ) ) { $decoded = json_decode( $schemas, true ); $schemas = JSON_ERROR_NONE === json_last_error() ? $decoded : array(); }
		if ( ! $schemas ) { return array(); }
		$schemas = isset( $schemas['@context'] ) || isset( $schemas['@type'] ) ? array( $schemas ) : (array) $schemas;
		$out = array();
		foreach ( $schemas as $schema ) { if ( is_array( $schema ) ) { if ( ! isset( $schema['@context'] ) ) { $schema['@context'] = 'https://schema.org'; } $out[] = $schema; } }
		return $out;
	}

	public static function render_managed_seo_head(): void {
		$record = self::current_seo_record(); if ( ! $record ) { return; }
		$provider = self::seo_provider();
		/* Basic tags are rendered only by PR STUDIO's native provider. When Rank Math
		 * or Yoast is active, post-level values are mirrored into that provider and we
		 * avoid duplicate title/description/canonical/robots/OG/Twitter output. */
		if ( 'prstudio_native' === $provider ) {
			if ( ! empty( $record['description'] ) ) { echo '<meta name="description" content="' . esc_attr( (string) $record['description'] ) . '" />' . "\n"; }
			if ( ! empty( $record['canonical'] ) ) { echo '<link rel="canonical" href="' . esc_url( (string) $record['canonical'] ) . '" />' . "\n"; }
			if ( ! empty( $record['robots'] ) ) { echo '<meta name="robots" content="' . esc_attr( (string) $record['robots'] ) . '" />' . "\n"; }
			foreach ( (array) ( $record['open_graph'] ?? array() ) as $property => $content ) { echo '<meta property="' . esc_attr( (string) $property ) . '" content="' . esc_attr( (string) $content ) . '" />' . "\n"; }
			foreach ( (array) ( $record['twitter'] ?? array() ) as $name => $content ) { echo '<meta name="' . esc_attr( (string) $name ) . '" content="' . esc_attr( (string) $content ) . '" />' . "\n"; }
		}
		foreach ( (array) ( $record['hreflang'] ?? array() ) as $lang => $href ) { echo '<link rel="alternate" hreflang="' . esc_attr( (string) $lang ) . '" href="' . esc_url( (string) $href ) . '" />' . "\n"; }
		if ( 'prstudio_native' === $provider ) { foreach ( self::normalized_record_schemas( $record ) as $schema ) { echo '<script type="application/ld+json">' . wp_json_encode( $schema, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE ) . '</script>' . "\n"; } }
	}

	public static function rank_math_json_ld( $data, $jsonld = null ) {
		if ( 'rank_math' !== self::seo_provider() ) { return $data; }
		if ( ! is_array( $data ) ) { $data = array(); }
		foreach ( self::normalized_record_schemas( self::current_seo_record() ) as $schema ) {
			$key = 'prstudio_' . sanitize_key( (string) ( $schema['@type'] ?? 'schema' ) ) . '_' . substr( hash( 'sha256', wp_json_encode( $schema ) ), 0, 8 );
			$data[ $key ] = $schema;
		}
		return $data;
	}

	public static function yoast_schema_graph( $graph, $context = null ) {
		if ( 'yoast' !== self::seo_provider() ) { return $graph; }
		if ( ! is_array( $graph ) ) { $graph = array(); }
		foreach ( self::normalized_record_schemas( self::current_seo_record() ) as $schema ) { $graph[] = $schema; }
		return $graph;
	}

	public static function render_managed_frontend_scripts(): void {
		$cfg = self::runtime_config(); foreach ( (array) ( $cfg['frontend_scripts'] ?? array() ) as $id => $entry ) {
			if ( ! is_array( $entry ) || empty( $entry['enabled'] ) ) { continue; }
			$script = (string) ( $entry['script'] ?? '' ); if ( '' === trim( $script ) ) { continue; }
			echo '<script data-prstudio-script="' . esc_attr( (string) $id ) . '">' . $script . '</script>' . "\n"; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- explicitly managed script payload.
		}
	}

	public static function filter_robots_txt( string $output, bool $public ): string {
		$cfg = self::runtime_config(); $managed = (string) ( $cfg['robots_txt'] ?? '' ); return '' !== trim( $managed ) ? $managed : $output;
	}

	public static function send_managed_security_headers(): void {
		$cfg = self::runtime_config(); $headers = is_array( $cfg['security_headers'] ?? null ) ? $cfg['security_headers'] : array();
		foreach ( $headers as $name => $value ) { if ( preg_match( '/^[A-Za-z0-9-]{2,80}$/', (string) $name ) && is_scalar( $value ) && ! headers_sent() ) { header( $name . ': ' . str_replace( array( "\r", "\n" ), '', (string) $value ), true ); } }
	}

	public static function enforce_blocked_ips(): void {
		if ( is_admin() && current_user_can( 'manage_options' ) ) { return; }
		$cfg = self::runtime_config(); $ip = sanitize_text_field( wp_unslash( (string) ( $_SERVER['REMOTE_ADDR'] ?? '' ) ) );
		if ( $ip && in_array( $ip, (array) ( $cfg['blocked_ips'] ?? array() ), true ) ) { status_header( 403 ); exit; }
	}
	private static function route_backup_manage( string $action, array $args ) {
