			$id = 'checkpoint-' . gmdate( 'Ymd-His' ) . '-' . substr( wp_generate_uuid4(), 0, 8 ); $dest = $root . $id; if ( ! wp_mkdir_p( $dest ) ) { return new WP_Error( 'prstudio_backup_mkdir_failed', 'Impossibile creare il checkpoint.', array( 'status' => 500 ) ); }
			$manifest = array( 'backup_id' => $id, 'scope' => $scope, 'source' => self::rel_path( $source ), 'created_at' => gmdate( DATE_ATOM ), 'files' => array() ); $count = 0;
			$copy_one = static function( string $file, string $relative ) use ( $dest, &$manifest, &$count ) {
