				$manifest['files'][] = array( 'path' => $relative, 'bytes' => filesize( $file ), 'sha256' => hash_file( 'sha256', $file ) );
			};
			try {
				if ( is_file( $source ) ) { $copy_one( $source, basename( $source ) ); }
				else { $it = new RecursiveIteratorIterator( new RecursiveDirectoryIterator( $source, FilesystemIterator::SKIP_DOTS ) ); foreach ( $it as $file ) { if ( ! $file->isFile() ) { continue; } if ( 0 === strpos( wp_normalize_path( $file->getPathname() ), wp_normalize_path( $root ) ) ) { continue; } $relative = ltrim( substr( wp_normalize_path( $file->getPathname() ), strlen( trailingslashit( wp_normalize_path( $source ) ) ) ), '/' ); $copy_one( $file->getPathname(), $relative ); } }
			} catch ( Throwable $e ) { self::remove_tree_raw( $dest ); return new WP_Error( 'prstudio_backup_create_failed', $e->getMessage(), array( 'status' => 500 ) ); }
			$manifest['count'] = count( $manifest['files'] ); $manifest['manifest_sha256'] = hash( 'sha256', wp_json_encode( $manifest['files'] ) ); file_put_contents( trailingslashit( $dest ) . 'meta.json', wp_json_encode( $manifest, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES ) );
			return self::mutation( array( 'backup_id' => $id, 'created' => true, 'count' => $manifest['count'], 'manifest_sha256' => $manifest['manifest_sha256'] ) );
		}
		if ( 'prune' === $action ) {
			$keep = max( 1, min( 100, (int) self::v( $args, 'keep', 10 ) ) ); $dirs = array_values( array_filter( glob( $root . '*' ) ?: array(), 'is_dir' ) ); usort( $dirs, static fn( $a, $b ) => filemtime( $b ) <=> filemtime( $a ) ); $removed = array();
			foreach ( array_slice( $dirs, $keep ) as $dir ) { $id = basename( $dir ); if ( self::remove_tree_raw( $dir ) ) { $removed[] = $id; } }
			$remaining = array_values( array_filter( glob( $root . '*' ) ?: array(), 'is_dir' ) ); return self::mutation( array( 'pruned' => count( $removed ), 'removed' => $removed, 'remaining' => count( $remaining ), 'keep' => $keep ) );
		}
