	}

	private static function remove_tree_raw( string $dir ): bool {
		if ( ! is_dir( $dir ) ) { return ! file_exists( $dir ) || @unlink( $dir ); }
		$it = new RecursiveIteratorIterator( new RecursiveDirectoryIterator( $dir, FilesystemIterator::SKIP_DOTS ), RecursiveIteratorIterator::CHILD_FIRST ); foreach ( $it as $file ) { $file->isDir() ? @rmdir( $file->getPathname() ) : @unlink( $file->getPathname() ); } return @rmdir( $dir );
