	private static function route_comments_manage( string $action, array $args ) {
		if ( ! in_array( $action, array( 'approve', 'bulk_moderate', 'hold', 'restore', 'spam', 'trash', 'unspam' ), true ) ) { return new WP_Error( 'prstudio_comments_action_unhandled', 'Azione commenti non gestita.', array( 'status' => 500, 'action' => $action ) ); }
		$ids = self::ids( $args ); if ( ! $ids ) { return new WP_Error( 'prstudio_comment_id_required', 'id/ids obbligatorio.', array( 'status' => 400 ) ); }
		$status_map = array( 'approve' => 'approve', 'hold' => 'hold', 'spam' => 'spam', 'trash' => 'trash', 'unspam' => 'approve', 'restore' => 'approve' );
		$target = 'bulk_moderate' === $action ? sanitize_key( (string) self::v( $args, 'status', 'approve' ) ) : ( $status_map[ $action ] ?? '' );
		if ( ! in_array( $target, array( 'approve', 'hold', 'spam', 'trash' ), true ) ) { return new WP_Error( 'prstudio_comment_status_invalid', 'Stato commento non valido.', array( 'status' => 400 ) ); }
		$out = array(); $ok = 0;
		foreach ( $ids as $id ) {
			if ( 'restore' === $action && function_exists( 'wp_untrash_comment' ) ) { $r = wp_untrash_comment( $id ); }
			elseif ( 'unspam' === $action && function_exists( 'wp_unspam_comment' ) ) { $r = wp_unspam_comment( $id ); }
			else { $r = wp_set_comment_status( $id, $target, true ); }
