			$out[] = array( 'id' => $id, 'result' => (bool) $r, 'verified' => (bool) $verified, 'status' => $c ? (string) $c->comment_approved : null );
		}
		return self::mutation( array( 'processed' => count( $ids ), 'succeeded' => $ok, 'failed' => count( $ids ) - $ok, 'items' => $out ), $ok === count( $ids ) );
	}

	private static function route_cron_manage( string $action, array $args ) {
		if ( ! function_exists( 'as_get_scheduled_actions' ) && ! class_exists( 'ActionScheduler' ) ) { return new WP_Error( 'prstudio_action_scheduler_unavailable', 'Action Scheduler non disponibile.', array( 'status' => 503 ) ); }
		$hook = sanitize_key( (string) self::v( $args, 'hook', '' ) ); $group = sanitize_key( (string) self::v( $args, 'group', '' ) ); $action_id = absint( self::v( $args, 'action_id', self::v( $args, 'id', 0 ) ) );
		if ( 'action_scheduler_list' === $action ) {
