			$out = array(); foreach ( $items as $id => $obj ) { $out[] = array( 'id' => is_numeric( $id ) ? (int) $id : null, 'hook' => method_exists( $obj, 'get_hook' ) ? $obj->get_hook() : '', 'args' => method_exists( $obj, 'get_args' ) ? $obj->get_args() : array(), 'group' => method_exists( $obj, 'get_group' ) ? $obj->get_group() : '', 'status' => method_exists( $obj, 'get_status' ) ? $obj->get_status() : '' ); } return array( 'items' => $out, 'count' => count( $out ) );
