			elseif ( $hook && function_exists( 'as_unschedule_action' ) ) { $cancelled = (bool) as_unschedule_action( $hook, (array) self::v( $args, 'args', array() ), $group ); }
			if ( ! $cancelled ) { return new WP_Error( 'prstudio_action_scheduler_cancel_failed', 'Nessuna action cancellata.', array( 'status' => 404 ) ); } return self::mutation( array( 'cancelled' => true, 'action_id' => $action_id ?: null, 'hook' => $hook ) );
