	private static function route_commerce_settings_manage( string $action, array $args ) {
		$routes = array(
			'get_reports' => array( 'GET', '/wc-analytics/reports/revenue/stats' ),
			'get_system_status' => array( 'GET', '/wc/v3/system_status' ),
			'manage_gateways' => array( 'GET', '/wc/v3/payment_gateways' ),
			'manage_shipping_methods' => array( 'GET', '/wc/v3/shipping_methods' ),
			'manage_shipping_zones' => array( 'GET', '/wc/v3/shipping/zones' ),
			'manage_tax_classes' => array( 'GET', '/wc/v3/taxes/classes' ),
			'manage_tax_rates' => array( 'GET', '/wc/v3/taxes' ),
			'manage_webhooks' => array( 'GET', '/wc/v3/webhooks' ),
		);
		if ( ! isset( $routes[ $action ] ) ) { return new WP_Error( 'prstudio_wc_settings_action_unhandled', 'Azione WooCommerce settings non gestita.', array( 'status' => 500 ) ); }
		[ $default_method, $base_route ] = $routes[ $action ];
		$id = absint( self::v( $args, 'id', 0 ) );
		$route = $base_route . ( $id ? '/' . $id : '' );
		$method = strtoupper( (string) self::v( $args, 'method', $default_method ) );
		$body = (array) self::v( $args, 'body', self::v( $args, 'changes', array() ) );
		$query = (array) self::v( $args, 'query', array() );
		if ( $body && 'GET' === $method ) { $method = $id ? 'PUT' : 'POST'; }
		$result = self::rest( $method, $route, $query, $body );
		if ( is_wp_error( $result ) ) { return $result; }
		if ( 'GET' === $method ) { return self::verified_no_change( $result, 'woocommerce_rest_read' ); }
		$verify = $id ? self::rest( 'GET', $route ) : null;
		$verified = ! $id || ( ! is_wp_error( $verify ) && isset( $verify['data'] ) );
		return self::mutation( array( 'write' => $result, 'readback' => $verify ), $verified, $verified ? 'woocommerce_rest_readback' : 'woocommerce_rest_unverified' );
	}

