	private static function require_woocommerce() {
		return function_exists('wc_get_product') && function_exists('wc_get_order') ? true : new WP_Error('prstudio_woocommerce_unavailable','WooCommerce non disponibile.',array('status'=>503));
	}

	private static function product_ids_wc( array $args ): array {
		$ids=self::ids($args,'product_id','product_ids');if($ids)return $ids;if(!function_exists('wc_get_products'))return array();$q=array('limit'=>self::limit($args,50,self::MAX_BATCH),'return'=>'ids','status'=>(string)self::v($args,'status','publish'));$search=(string)self::v($args,'search','');if($search)$q['s']=$search;return array_map('absint',(array)wc_get_products($q));
	}

	private static function product_map( array $ids ): array {
		$ids = array_values( array_unique( array_filter( array_map( 'absint', $ids ) ) ) );
		if ( ! $ids ) { return array(); }
		$out = array();
		if ( function_exists( 'wc_get_products' ) ) {
			$products = wc_get_products( array( 'include'=>$ids, 'limit'=>count( $ids ), 'return'=>'objects' ) );
			foreach ( (array) $products as $product ) { if ( is_object( $product ) && method_exists( $product, 'get_id' ) ) { $out[ (int) $product->get_id() ] = $product; } }
		}
		if ( count( $out ) < count( $ids ) ) { foreach ( $ids as $id ) { if ( ! isset( $out[ $id ] ) ) { $product = wc_get_product( $id ); if ( $product ) { $out[ $id ] = $product; } } } }
		return $out;
	}

	private static function product_snapshot( $p ): array {
		return array('id'=>$p->get_id(),'name'=>$p->get_name(),'status'=>$p->get_status(),'sku'=>$p->get_sku(),'price'=>$p->get_price(),'regular_price'=>$p->get_regular_price(),'sale_price'=>$p->get_sale_price(),'stock_status'=>$p->get_stock_status(),'stock_quantity'=>$p->get_stock_quantity(),'manage_stock'=>$p->get_manage_stock(),'type'=>$p->get_type(),'categories'=>$p->get_category_ids(),'tags'=>$p->get_tag_ids(),'date_modified'=>$p->get_date_modified()?$p->get_date_modified()->date(DATE_ATOM):null);
	}

	private static function apply_product_changes( $p, array $changes ): array {
		$map=array('name'=>'set_name','status'=>'set_status','sku'=>'set_sku','regular_price'=>'set_regular_price','sale_price'=>'set_sale_price','description'=>'set_description','short_description'=>'set_short_description','stock_quantity'=>'set_stock_quantity','stock_status'=>'set_stock_status','manage_stock'=>'set_manage_stock','featured'=>'set_featured','catalog_visibility'=>'set_catalog_visibility','weight'=>'set_weight','length'=>'set_length','width'=>'set_width','height'=>'set_height','tax_status'=>'set_tax_status','tax_class'=>'set_tax_class');$applied=[];foreach($map as $key=>$method){if(array_key_exists($key,$changes)&&method_exists($p,$method)){$p->{$method}($changes[$key]);$applied[]=$key;}}if(isset($changes['category_ids'])&&method_exists($p,'set_category_ids')){$p->set_category_ids(array_map('absint',(array)$changes['category_ids']));$applied[]='category_ids';}if(isset($changes['tag_ids'])&&method_exists($p,'set_tag_ids')){$p->set_tag_ids(array_map('absint',(array)$changes['tag_ids']));$applied[]='tag_ids';}foreach((array)($changes['meta']??array()) as $k=>$v){$p->update_meta_data(sanitize_key((string)$k),$v);$applied[]='meta:'.sanitize_key((string)$k);}return $applied;
	}

	private static function route_inventory_manage( string $action, array $args ) {
		$wc=self::require_woocommerce();if(is_wp_error($wc))return $wc;$ids=self::product_ids_wc($args);$product_map=self::product_map($ids);
		if('bulk_get'===$action){$items=[];foreach($ids as $id){$p=$product_map[$id]??null;if($p)$items[]=self::product_snapshot($p);}return self::verified_no_change(array('items'=>$items,'count'=>count($items)),'inventory_bulk_get');}
