	private static function run_process( array $command, string $cwd, int $timeout = 60, int $max_output = 1048576 ) {
		if ( ! function_exists( 'proc_open' ) || ! $command ) { return new WP_Error( 'prstudio_process_unavailable', 'proc_open non disponibile.', array( 'status' => 503 ) ); }
		$exe=(string)$command[0]; if(str_contains($exe,'/')||str_contains($exe,'\\')){if(!is_executable($exe))return new WP_Error('prstudio_process_binary_missing','Binario non eseguibile.',array('status'=>503,'binary'=>$exe));}else{ $paths=explode(PATH_SEPARATOR,(string)getenv('PATH'));$found=false;foreach($paths as $dir){$candidate=rtrim($dir,DIRECTORY_SEPARATOR).DIRECTORY_SEPARATOR.$exe;if(is_file($candidate)&&is_executable($candidate)){$command[0]=$candidate;$found=true;break;}}if(!$found)return new WP_Error('prstudio_process_binary_missing','Binario non trovato nel PATH.',array('status'=>503,'binary'=>$exe)); }
		$desc=array(0=>array('pipe','r'),1=>array('pipe','w'),2=>array('pipe','w'));$proc=@proc_open($command,$desc,$pipes,$cwd,null,array('bypass_shell'=>true));if(!is_resource($proc))return new WP_Error('prstudio_process_start_failed','Impossibile avviare processo.',array('status'=>500));fclose($pipes[0]);stream_set_blocking($pipes[1],false);stream_set_blocking($pipes[2],false);$start=microtime(true);$stdout='';$stderr='';$timed=false;do{$status=proc_get_status($proc);$stdout.=stream_get_contents($pipes[1]);$stderr.=stream_get_contents($pipes[2]);if(strlen($stdout)+strlen($stderr)>$max_output){$stderr.="\n[output truncated]";$stdout=substr($stdout,0,$max_output/2);$stderr=substr($stderr,0,$max_output/2);proc_terminate($proc,9);break;}if(microtime(true)-$start>$timeout){$timed=true;proc_terminate($proc,15);usleep(100000);$st=proc_get_status($proc);if($st['running'])proc_terminate($proc,9);break;}usleep(20000);}while(!empty($status['running']));$stdout.=stream_get_contents($pipes[1]);$stderr.=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$exit=proc_close($proc);if($timed)return new WP_Error('prstudio_process_timeout','Processo terminato per timeout.',array('status'=>504,'command'=>$exe));return array('exit_code'=>$exit,'stdout'=>$stdout,'stderr'=>$stderr,'ok'=>0===$exit,'command'=>array_map('strval',$command));
	}

	private static function plugin_target( array $args, bool $must_exist = true ): array {
		self::ensure_admin_include('plugin.php');$plugin=(string)self::v($args,'plugin',self::v($args,'slug',''));if(!$plugin)return array('error'=>new WP_Error('prstudio_plugin_required','plugin/slug obbligatorio.',array('status'=>400)));
		$plugins=get_plugins();$file='';if(isset($plugins[$plugin]))$file=$plugin;else{foreach($plugins as $candidate=>$data){if(dirname($candidate)===$plugin||sanitize_title((string)($data['Name']??''))===sanitize_title($plugin)){$file=$candidate;break;}}}
		if(!$file){$candidate=$plugin.'/'.$plugin.'.php';if(is_file(WP_PLUGIN_DIR.'/'.$candidate))$file=$candidate;}
		if(!$file&&$must_exist)return array('error'=>new WP_Error('prstudio_plugin_not_found','Plugin non trovato.',array('status'=>404,'plugin'=>$plugin)));
		$slug=$file?dirname($file):sanitize_key($plugin);if('.'===$slug)$slug=pathinfo($file,PATHINFO_FILENAME);$root=wp_normalize_path(WP_PLUGIN_DIR.'/'.$slug);return array('file'=>$file,'slug'=>$slug,'root'=>$root,'main'=>$file?wp_normalize_path(WP_PLUGIN_DIR.'/'.$file):wp_normalize_path(WP_PLUGIN_DIR.'/'.$slug.'/'.$slug.'.php'),'data'=>$file?($plugins[$file]??array()):array());
