	private static function recursive_replace_value( $value, string $search, string $replace, bool $regex, int &$count ) {
		if ( is_array( $value ) ) { foreach ( $value as $k => $v ) { $value[ $k ] = self::recursive_replace_value( $v, $search, $replace, $regex, $count ); } return $value; }
		if ( is_object( $value ) ) { foreach ( get_object_vars( $value ) as $k => $v ) { $value->{$k} = self::recursive_replace_value( $v, $search, $replace, $regex, $count ); } return $value; }
		if ( ! is_string( $value ) ) { return $value; }
		return self::replace_string_counted( $value, $search, $replace, $regex, $count );
	}

	private static function replace_string_counted( string $text, string $search, string $replace, bool $regex, int &$count ): string {
		if($regex){$out=@preg_replace($search,$replace,$text,-1,$n);if(null===$out)throw new InvalidArgumentException('Regex non valida.');$count+=$n;return $out;}$out=str_replace($search,$replace,$text,$n);$count+=$n;return $out;
	}

	private static function db_search_rows( string $needle, int $limit = 200 ): array {
