		$out['termmeta']=$wpdb->get_results($wpdb->prepare("SELECT meta_id,term_id,meta_key,meta_value FROM {$wpdb->termmeta} WHERE meta_value LIKE %s LIMIT %d",$like,$limit),ARRAY_A)?:array();
		$out['usermeta']=$wpdb->get_results($wpdb->prepare("SELECT umeta_id,user_id,meta_key,meta_value FROM {$wpdb->usermeta} WHERE meta_value LIKE %s LIMIT %d",$like,$limit),ARRAY_A)?:array();
